Balance invariant (Nievergelt-Reingold / Adams / Haskell Data.Set scheme):
for every node with children sizes ``sl`` and ``sr``:

    sl + sr <= 1   OR   max(sl, sr) <= DELTA * min(sl, sr)

with DELTA = 3 and RATIO = 2. Rebalancing happens on the spine during
insert/delete; only O(log n) nodes are freshly allocated per update.
"""

DELTA = 3
RATIO = 2


class _Node:
    """An immutable tree node. Never mutated after construction."""

    __slots__ = ("size", "left", "key", "value", "right")

    def __init__(self, size, left, key, value, right):
        self.size = size
        self.left = left
        self.key = key
        self.value = value
        self.right = right


def _size(node):
    return 0 if node is None else node.size


def _mknode(left, key, value, right):
    return _Node(_size(left) + _size(right) + 1, left, key, value, right)


def _rotate_l(l, key, value, r):
    """Precondition: _size(r) > DELTA * _size(l)."""
    rl = r.left
    rr = r.right
    if _size(rl) < RATIO * _size(rr):
        # single left rotation
        return _mknode(_mknode(l, key, value, rl), r.key, r.value, rr)
    # double left rotation
    rll = rl.left
    rlr = rl.right
    return _mknode(
        _mknode(l, key, value, rll), rl.key, rl.value, _mknode(rlr, r.key, r.value, rr)
    )


def _rotate_r(l, key, value, r):
    """Precondition: _size(l) > DELTA * _size(r). Mirror of _rotate_l."""
    ll = l.left
    lr = l.right
    if _size(lr) < RATIO * _size(ll):
        # single right rotation
        return _mknode(ll, l.key, l.value, _mknode(lr, key, value, r))
    # double right rotation
    lrl = lr.left
    lrr = lr.right
    return _mknode(
        _mknode(ll, l.key, l.value, lrl), lr.key, lr.value, _mknode(lrr, key, value, r)
    )


def _balance(left, key, value, right):
    """Rebuild a node from children, restoring the weight-balance invariant."""
    sl = _size(left)
    sr = _size(right)
    total = sl + sr
    if total <= 1:
        return _mknode(left, key, value, right)
    if sr > DELTA * sl:
        return _rotate_l(left, key, value, right)
    if sl > DELTA * sr:
        return _rotate_r(left, key, value, right)
    return _mknode(left, key, value, right)


def _insert(node, key, value):
    """Insert or overwrite; returns the new (sub)tree root."""
    if node is None:
        return _mknode(None, key, value, None)
    if key < node.key:
        return _balance(_insert(node.left, key, value), node.key, node.value, node.right)
    if key > node.key:
        return _balance(node.left, node.key, node.value, _insert(node.right, key, value))
    # overwrite existing key: fresh node, old one untouched
    return _mknode(node.left, key, value, node.right)


def _delete_find_max(node):
    """Return ((max_key, max_value), tree_without_max). Assumes node is not None
    and node.right is not None at top level of recursion."""
    if node.right is None:
        return (node.key, node.value), node.left
    kv, new_right = _delete_find_max(node.right)
    return kv, _balance(node.left, node.key, node.value, new_right)


def _glue(left, right):
    """Join two balanced subtrees where every left key < every right key."""
    if left is None:
        return right
    if right is None:
        return left
    if _size(left) > _size(right):
        (mkey, mval), new_left = _delete_find_max(left)
        return _balance(new_left, mkey, mval, right)
    (mkey, mval), new_right = _delete_find_min(right)
    return _balance(left, mkey, mval, new_right)


def _delete_find_min(node):
    """Return ((min_key, min_value), tree_without_min)."""
    if node.left is None:
        return (node.key, node.value), node.right
    kv, new_left = _delete_find_min(node.left)
    return kv, _balance(new_left, node.key, node.value, node.right)


def _delete(node, key):
    """Delete key if present; returns the new (sub)tree root (unchanged if absent)."""
    if node is None:
        return None
    if key < node.key:
        return _balance(_delete(node.left, key), node.key, node.value, node.right)
    if key > node.key:
        return _balance(node.left, node.key, node.value, _delete(node.right, key))
    return _glue(node.left, node.right)


def _find(node, key):
    while node is not None:
        if key < node.key:
            node = node.left
        elif key > node.key:
            node = node.right
        else:
            return node.value
    return None


def _iter_items(node):
    stack = []
    while stack or node is not None:
        while node is not None:
            stack.append(node)
            node = node.left
        node = stack.pop()
        yield node.key, node.value
        node = node.right
