result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "tests/pmap_helpers.py", "content": """"Invariant checker for the weight-balanced tree used by persistent_map.

Verifies, for every node:
  1. cached ``size`` equals left_size + right_size + 1,
  2. BST ordering (all left keys < node key < all right keys),
  3. the weight-balance condition:
       size(l) + size(r) <= 1
         or max(size(l), size(r)) <= DELTA * min(size(l), size(r))
"""

from persistent_map._wbtree import DELTA


class BalanceViolation(AssertionError):
    pass


def check_balance_invariants(root):
    """Return tree height; raise BalanceViolation on any violation."""

    def walk(node):
        if node is None:
            return 0

        lh = walk(node.left)
        rh = walk(node.right)

        sl = 0 if node.left is None else node.left.size
        sr = 0 if node.right is None else node.right.size

        if node.size != sl + sr + 1:
            raise BalanceViolation(
                f"bad size at node {node.key!r}: {node.size} != {sl}+{sr}+1"
            )

        if node.left is not None and not _max_key(node.left) < node.key:
            raise BalanceViolation(f"BST order violated in left subtree of {node.key!r}")
        if node.right is not None and not node.key < _min_key(node.right):
            raise BalanceViolation(f"BST order violated in right subtree of {node.key!r}")

        if sl + sr > 1 and max(sl, sr) > DELTA * min(sl, sr):
            raise BalanceViolation(
                f"weight balance violated at node {node.key!r}: sizes {sl}, {sr}"
            )

        return 1 + max(lh, rh)

    def _min_key(node):
        while node.left is not None:
            node = node.left
        return node.key

    def _max_key(node):
        while node.right is not None:
            node = node.right
        return node.key

    return walk(root)
